"""Additional practical coordinate proofs, triangles and quadrilaterals, printed p. 269."""
import json,argparse
from itertools import permutations
from coordinate_additional_vectors import ROOT,BOOK,card,panel,text,radical
from coordinate_actions import pair_answer

OUT=ROOT/'geometry-course/textbook/data/coordinate-additional-figures.json'


def d2(a,b):return sum((x-y)**2 for x,y in zip(a,b,strict=True))


def mid(a,b):return tuple((x+y)/2 for x,y in zip(a,b,strict=True))


def scene(label,points,edges,u=1):
    return panel(label,{k:(x/u,y/u) for k,(x,y) in points.items()},edges)


def triangle(n):
    old={'A':(4,8),'B':(12,11),'C':(7,0)} if n==1079 else {'A':(-5,6),'B':(3,-9),'C':(-12,-17)}
    new={'A':(1,-1),'B':(4,1),'C':(-1,2)} if n==1079 else {'A':(-1,4),'B':(2,2),'C':(4,-1)}
    ab,bc,ac=[d2(old[k],old[l]) for k,l in ('AB','BC','AC')]
    task='Докажи, что треугольник равнобедренный, но не равносторонний.' if n==1079 else 'Докажи, что углы A и C равны.'
    conclusion='AB=AC, тогда как квадрат BC вдвое больше квадрата AB. Равны две стороны, а не все три.' if n==1079 else 'AB=BC, поэтому у основания AC углы A и C равны: они лежат напротив равных сторон.'
    reason=f'AB²={ab}, BC²={bc}, AC²={ac}. '+conclusion
    steps=[('Вычисли три квадрата',f'Дважды вычти одноимённые координаты и сложи квадраты разностей. Для AB получаем ({old["B"][0]}−({old["A"][0]}))²+({old["B"][1]}−({old["A"][1]}))²={ab}; для BC и AC получаются {bc} и {ac}.','Для сравнения положительных длин достаточно сравнить их квадраты.'),
           ('Укажи геометрическое следствие',conclusion,'Отнеси каждую длину и каждый угол к правильным буквам.'),
           ('Проверь на другом треугольнике','Новые точки '+', '.join(k+'='+text(p) for k,p in new.items())+'. Для двух равных сторон квадраты равны 13, а у третьей получается '+str(d2(new['B'],new['C']) if n==1079 else d2(new['A'],new['C']))+'.','В новом примере снова отметь равные стороны и углы напротив них.')]
    return card(n,None,', '.join(k+'='+text(p) for k,p in old.items())+'. '+task,reason,'Сравни квадраты всех нужных расстояний. Угол A лежит напротив BC, угол C — напротив AB.',steps,[scene('Исходный треугольник',old,'AB BC CA',2),scene('Сравни выделенные стороны',old,'AB AC' if n==1079 else 'AB BC',2),scene('Другие вершины',new,'AB BC CA',2)],[('Каков квадрат исходной стороны AB?',str(ab),'Сложи квадраты разностей координат A и B.'),('Каков квадрат каждой из двух равных сторон нового треугольника?','13','Проекции одной из этих сторон имеют длины 2 и 3.')],[96],2)


def radii(part):
    old={'D':(1,1),'A':(5,4),'B':(4,-3),'C':(-2,5)} if part=='а' else {'D':(1,0),'A':(7,-8),'B':(-5,8),'C':(9,6)}
    new={'D':(-1,2),'A':(2,2),'B':(-1,5),'C':(-4,2)} if part=='а' else {'D':(2,-1),'A':(5,3),'B':(-1,3),'C':(2,-6)}
    sq=d2(old['D'],old['A']);r=radical(sq);nf=d2(new['D'],new['A'])
    dif={k:tuple(x-y for x,y in zip(old[k],old['D'],strict=True)) for k in 'ABC'}
    reason='У смещений DA, DB и DC координаты '+', '.join(text(dif[k]) for k in 'ABC')+f'. Все три суммы квадратов равны {sq}. Получаем DA=DB=DC={r}.'
    return card(1081,part,', '.join(k+'='+text(p) for k,p in old.items())+'. Обоснуй равенство расстояний от D до A, B и C.',reason,'Вычитай координаты одного и того же центра D. Для доказательства нужны все три расстояния.',[('Сравни DA и DB',f'Смещения DA={text(dif["A"])} и DB={text(dif["B"])} могут иметь разные координаты, но у обоих квадрат длины {sq}.','Важно равенство длин, а не равенство направлений.'),('Проверь ещё DC',f'DC={text(dif["C"])} даёт тот же квадрат {sq}. Значит, три точки находятся на окружности радиуса {r} с центром D.','Одинаковые неотрицательные квадраты дают равные расстояния.'),('Смени центр и все точки','При '+', '.join(k+'='+text(p) for k,p in new.items())+f' три квадрата равны {nf}. Новый общий радиус {radical(nf)}.','Прежде чем извлекать корень, проверь третью точку.')],[scene('Первые два расстояния',old,'DA DB',2),scene('Три исходных расстояния',old,'DA DB DC',2),scene('Новый центр',new,'DA DB DC',2)],[('Каков квадрат исходного расстояния DC?',str(sq),'Сложи квадраты обеих координат смещения DC.'),('Каков новый радиус?',radical(nf),'Корень из общего квадрата расстояний даёт длину.')],[96,98],2)


def center():
    old={'A':(-2,4),'B':(6,8),'P':(5,0)};new={'A':(0,2),'B':(4,2),'P':(2,0)}
    c=card(1082,None,'Найди на оси Ox точку P, одинаково удалённую от A=(−2;4) и B=(6;8). Почему решение единственно?','P=(5;0). Для P=(x;0) равенство квадратов расстояний даёт (x+2)²+16=(x−6)²+64. После сокращения 16x=80. Для x=5 оба квадрата равны 65.','Ордината точки на Ox равна нулю, а абсциссу нужно найти.',[('Запиши два квадрата','Вычитая пару (x;0) из координат A и B, получаем PA²=(x+2)²+16 и PB²=(x−6)²+64.','Высота каждой заданной точки над осью влияет на расстояние.'),('Устрани квадратичный член','Раскрытие даёт x²+4x+20=x²−12x+100. Единственный корень x=5. Для P=(5;0): PA²=49+16=65, PB²=1+64=65.','Положительные расстояния равны, если равны их квадраты.'),('Сравни пример с равными высотами','При A=(0;2), B=(4;2) высоты равны, и x²=(x−4)². Тогда P=(2;0).','Половина суммы абсцисс подходит для двух одинаковых высот.')],[scene('Исходные A и B',{k:v for k,v in old.items() if k!='P'},'AB',2),scene('Два равных расстояния от оси',old,'PA PB',2),scene('Новая пара на одной высоте',new,'PA PB',2)],[('Каков общий квадрат расстояний из найденной точки?','65','Вычисли 7²+4².'),('Какова абсцисса нового P?','2','Реши x²=(x−4)².')],[96,99],2)
    return pair_answer(c,(5,0),'Назови обе координаты, сохрани нулевую ординату. Приравняй (x+2)²+16 и (x−6)²+64.')


def mids():
    old={'A':(-5,13),'B':(3,5),'C':(-3,-1)};new={'A':(-4,0),'B':(2,0),'C':(0,8)}
    for p in (old,new):
        p.update(K=mid(p['A'],p['B']),L=mid(p['B'],p['C']),M=mid(p['C'],p['A']))
    begin='Треугольник задан A=(−5;13), B=(3;5), C=(−3;−1). '
    rows=[]
    data=[('а','Найди середины K стороны AB, L стороны BC и M стороны CA.',
        'K=(−1;9), L=(0;2), M=(−4;6). Для каждой точки складываем координаты концов соответствующей стороны и делим обе суммы на два.',
        'Для K усредни A и B. Для L нужны B и C, а для M нужны C и A.',
        [('Вычисли K','Суммы одноимённых координат A и B равны −2 и 18. Деление на два даёт K=(−1;9).','Усредни и абсциссы, и ординаты.'),('Найди L и M','На BC: ((3−3)/2;(5−1)/2)=(0;2). На CA: ((−3−5)/2;(−1+13)/2)=(−4;6).','L находится на Oy: нулевая абсцисса разрешена.'),('Другой треугольник','На новых сторонах с вершинами A=(−4;0), B=(2;0), C=(0;8) середины равны K=(−1;0), L=(1;4), M=(−2;4).','Сравни векторы от концов к каждой середине.')],
        'AB BC CA KL LM MK',[('Какова ордината исходной M?','6','Усредни −1 и 13.'),('Какова абсцисса новой L?','1','Усредни 2 и 0.')],
        'Введи xK;yK;xL;yL;xM;yM через точку с запятой.',['-1;9;0;2;-4;6','-1; 9; 0; 2; -4; 6','(-1;9);(0;2);(-4;6)','(-1; 9); (0; 2); (-4; 6)']),
      ('б','Найди длину медианы к AC.','Середина AC — M=(−4;6). Для медианы, выходящей из B, BM²=(−4−3)²+(6−5)²=50, значит BM=5√2.',
        'Определи, какая из вершин лежит напротив стороны AC. Из неё проведи отрезок к середине AC.',
        [('Отметь конец медианы','Усредняя координаты A и C, получаем M=(−4;6). Начало медианы — B=(3;5).','Медиана соединяет вершину с серединой противоположной стороны.'),('Вычисли квадрат и длину','Смещение от B к M равно (−7;1). Квадрат длины 49+1=50, откуда BM=5√2.','В ответе требуется длина, а не 50.'),('Смени вершины','При A=(−4;0), B=(2;0), C=(0;8) середина AC имеет координаты (−2;4). Новый BM имеет смещение (−4;4), квадрат длины 32 и длину 4√2.','Сначала найди новую середину.')],
        'AB BC CA BM',[('Каков квадрат исходной медианы?','50','Сложи 7² и 1².'),('Каков квадрат новой медианы?','32','Сложи 4² и 4².')],
        'Введи длину медианы со знаком √ или через sqrt().',['5√2','√50','sqrt(50)','5*sqrt(2)','5sqrt(2)']),
      ('в','Найди длины трёх средних линий в порядке линий, параллельных AB, BC, CA.','Для середин K на AB, L на BC и M на CA получаем LM=4√2, MK=3√2, KL=5√2. Каждая средняя линия равна половине соответствующей стороны.',
        'Сравни среднюю линию с третьей стороной. Чтобы получить длину линии, дели пополам длину стороны.',
        [('Вычисли стороны','Квадраты длин AB, BC, CA равны 128, 72 и 200, поэтому длины равны 8√2, 6√2 и 10√2.','Укажи каждой стороне её собственную длину.'),('Сопоставь средние линии','LM параллельна AB и равна 4√2, MK параллельна BC и равна 3√2, KL параллельна CA и равна 5√2.','Делится сама длина, а не число под корнем.'),('Проверь на горизонтальной стороне','При A=(−4;0), B=(2;0), C=(0;8) получаем M=(−2;4), L=(1;4). Длина ML равна 3 — половине нового AB=6.','Горизонтальная линия позволяет проверить длину по разности абсцисс.')],
        'AB BC CA KL LM MK',[('Чему равен коэффициент при √2 у исходной LM?','4','Она вдвое короче AB.'),('Чему равна новая ML?','3','Вычти абсциссу −2 из 1.')],
        'Введи коэффициенты при √2 в порядке линий, параллельных AB, BC, CA, через точку с запятой.',['4;3;5','4; 3; 5','4√2;3√2;5√2','4√2; 3√2; 5√2'])]
    for part,task,reason,hint,steps,sides,probes,prompt,accepted in data:
        c=card(1083,part,begin+task,reason,hint,steps,[scene('Исходные точки и середины',old,'AB BC CA',2),scene('Построение для выбранного подпункта',old,sides,2),scene('Проверка на треугольнике с другими вершинами',new,sides,2)],probes,[96],2)
        c['answer']=dict(mode='exact',accepted=accepted,prompt=prompt,feedback=hint);rows.append(c)
    return rows

def quadrilateral(n):
    sq=n==1084
    old={'A':(3,2),'B':(0,5),'C':(-3,2),'D':(0,-1)} if sq else {'A':(-2,-3),'B':(1,4),'C':(8,7),'D':(5,0)}
    new={'A':(1,-2),'B':(4,2),'C':(0,5),'D':(-3,1)} if sq else {'A':(-4,0),'B':(0,3),'C':(4,0),'D':(0,-3)}
    start='Вершины в порядке обхода: '+', '.join(k+'='+text(p) for k,p in old.items())+'. '
    if sq:
        reason='AB²=BC²=CD²=DA²=18. Кроме того, AC²=36=AB²+BC². По обратной теореме Пифагора угол ABC прямой. Четырёхугольник с четырьмя равными сторонами является ромбом, а ромб с прямым углом — квадратом.'
        steps=[('Сравни четыре стороны','Смещения AB=(−3;3), BC=(−3;−3), CD=(3;−3), DA=(3;3). У каждого сумма квадратов равна 18, поэтому все четыре стороны равны.','Равенства четырёх сторон пока достаточно только для ромба.'),('Докажи прямой угол','У AC=(−6;0) квадрат длины 36. Равенство 18+18=36 в треугольнике ABC даёт прямой угол при B по обратной теореме Пифагора. Значит, получен квадрат.','Достаточно одного прямого угла ромба.'),('Проверь повёрнутый квадрат','Для A=(1;−2), B=(4;2), C=(0;5), D=(−3;1) все стороны имеют квадрат длины 25, AC²=50. Здесь также 25+25=50, вопрос о прямом угле решается так же.','Положение сторон относительно осей не входит в определение квадрата.')]
        task='Докажи, что ABCD — квадрат.';hint='Отдельно докажи равенство сторон и прямой угол. У ромба стороны равны и без прямого угла.'
        checks=[('Каков квадрат исходной диагонали AC?','36','Её концы имеют одинаковую ординату, абсциссы отличаются на 6.'),('Каков квадрат одной стороны нового квадрата?','25','Сложи 3² и 4².')]
    else:
        reason='Все четыре стороны имеют квадрат длины 58, поэтому ABCD — ромб. Диагонали AC=(10;10), BD=(4;−4) имеют длины 10√2 и 4√2. Их полупроизведение равно 40, что и даёт площадь.'
        steps=[('Сравни длины сторон','Векторы AB=(3;7), BC=(7;3), CD=(−3;−7), DA=(−7;−3) имеют одну и ту же длину √58. Четырёхугольник — ромб.','Одних двух соседних одинаковых сторон для этого вывода недостаточно.'),('Найди площадь ромба','У AC=(10;10) длина 10√2, у BD=(4;−4) длина 4√2. Диагонали ромба перпендикулярны, и S=AC·BD/2=40.','Полупроизведение берётся от длин диагоналей, не от их квадратов.'),('Проверь ромб на новых данных','У нового ромба A=(−4;0), B=(0;3), C=(4;0), D=(0;−3) все стороны равны 5. Диагонали лежат на осях, их длины 8 и 6, а площадь 24.','Свяжи каждую диагональ с парой противоположных вершин.')]
        task='Докажи, что ABCD — ромб, и вычисли его площадь.';hint='Проверь все четыре стороны, затем вычисли длины AC и BD. Площадь ромба равна половине произведения диагоналей.'
        checks=[('Каков общий квадрат исходной стороны?','58','Сложи 3² и 7².'),('Какова площадь нового ромба?','24','Раздели 8·6 на 2.')]
    c=card(n,None,start+task,reason,hint,steps,[scene('Стороны исходного четырёхугольника',old,'AB BC CD DA',2),scene('Проверяемые диагонали',old,'AB BC CD DA AC BD',2),scene('Другой четырёхугольник',new,'AB BC CD DA AC BD',2)],checks,[96],2)
    return c


def fourth():
    old={'A':(-4,4),'B':(-5,1),'C':(-1,5)}
    def missing(p,common):
        a,b=[p[k] for k in 'ABC' if k!=common];c=p[common];return tuple(x+y-z for x,y,z in zip(a,b,c,strict=True))
    def draw(p,common):
        names=[x for x in 'ABC' if x!=common];new=missing(p,common);points=dict(p,D=new)
        x,y=names
        return scene('У общей вершины '+common+' сходятся стороны',points,' '.join([common+x,x+'D','D'+y,y+common,x+y,common+'D']),2)
    new={'A':(1,1),'B':(5,1),'C':(2,4)}
    original=[draw(old,k) for k in 'ABC']
    reason='В качестве общей вершины двух заданных сторон можно выбрать A, B или C. Если общая A, то D=B+C−A=(−2;2); при общей B получаем D=A+C−B=(0;8); при общей C — D=A+B−C=(−8;0). Все три точки различны. Во всех случаях середины соответствующих диагоналей совпадают.'
    steps=[('Сначала зафиксируй порядок обхода','Если соседние стороны исходят из A, к B прибавляется смещение AC. Так получаем D=B+C−A=(−2;2). То же следует из равенства A+D=B+C для концов диагоналей.','Нельзя заранее считать какую-то из данных точек общей вершиной во всех построениях.'),('Рассмотри остальные варианты','Выбор общей B даёт A+C−B=(0;8), выбор общей C даёт A+B−C=(−8;0). Это три точки, поскольку данные вершины различны и не лежат на одной прямой. Каждый параллелограмм даёт один из этих трёх выборов.','Обход в другую сторону не создаёт новых точек.'),('Проверь на новом треугольнике','Для A=(1;1), B=(5;1), C=(2;4) при общей A получается D=(6;4); при общей B — D=(−2;4), при общей C — D=(4;−2).','Проверь выбранный вариант равенством сумм координат концов диагоналей.')]
    c=card(1086,None,'Три вершины параллелограмма имеют координаты A=(−4;4), B=(−5;1), C=(−1;5), а их порядок не задан. Найди все возможные четвёртые вершины и объясни, сколько решений получилось.',reason,'Выбери общую вершину двух соседних сторон. Две оставшиеся точки соединяет одна диагональ, а общую вершину с искомой — вторая, с той же серединой.',steps,[original[0],original[1],draw(new,'A'),original[2],draw(new,'B'),draw(new,'C')],[('Сколько разных возможных четвёртых вершин получается в исходной задаче?','3','Проверь все три выбора общей вершины.'),('Какова абсцисса новой четвёртой вершины при общей A?','6','Вычисли xB+xC−xA для новых точек.')],[95,96],2)
    # Keep the personal answer open until all three points are named, in any order.
    pts=['-2;2','0;8','-8;0'];formats=[]
    for order in permutations(pts):
        for pad in ('',' '):
            forms=['('+s.replace(';',';'+pad)+')' for s in order]
            formats.extend([(';'+pad).join(forms),(','+pad).join(forms),(';'+pad).join(s.replace(';',';'+pad) for s in order)])
    c['answer']=dict(mode='exact',prompt='Введи три найденные точки в любом порядке, например (1;2);(3;4);(5;6).',accepted=list(dict.fromkeys(formats)),feedback='Назови все три возможные точки. Для каждого выбора общей вершины вычти её координаты из суммы координат остальных двух.')
    return c


def build():return {'bookId':BOOK,'lessons':[triangle(1079),triangle(1080),radii('а'),radii('б'),center(),*mids(),quadrilateral(1084),quadrilateral(1085),fourth()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');opts=parser.parse_args()
    data=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if opts.check:assert data==OUT.read_text()
    else:OUT.write_text(data)
